 * steps carry the ICU-translated regex (\\uXXXX -> \\x{...}); java.util.regex
 * compiles every pattern verbatim, with ONE further documented translation —
 * ICU accepts the bare derived property \\p{Alphabetic} while Java requires
 * the Is-prefixed form \\p{IsAlphabetic} (identical property, same matches;
 * the fixture test pins the behavior). \\p{Cc} and \\p{N} are native Java
 * categories, and \\s runs under UNICODE_CHARACTER_CLASS so it matches the
 * ICU whitespace set. Regenerate only if the hub re-exports the tokenizer.
 */
sealed interface PhononNormalizerStep {
    data class Replace(val pattern: String, val replacement: String) : PhononNormalizerStep
    data object Strip : PhononNormalizerStep
    data class Prepend(val text: String) : PhononNormalizerStep
}

